        ], task('python', L('Genera con `pipe` un’immagine dal prompt `"una volpe nella neve"` usando `num_inference_steps=25` e salvala in `volpe.png`.', 'Generate with `pipe` an image from the prompt `"una volpe nella neve"` using `num_inference_steps=25` and save it as `volpe.png`.'), "immagine = None", [re('pipe\s*\(\s*["\']una volpe nella neve["\']', L('Il prompt', 'The prompt')), re('num_inference_steps\s*=\s*25', L('25 passi', '25 steps')), re('\.images\s*\[\s*0\s*\]', L('Prendi la prima immagine', 'You take the first image')), re('\.save\s*\(\s*["\']volpe\.png["\']\s*\)', L('La salvi', 'You save it'))], '', "immagine = pipe(\"una volpe nella neve\", num_inference_steps=25).images[0]\nimmagine.save(\"volpe.png\")"), [
            dMatch(pMatch(), [[L('Rumore', 'Noise'), L('Punto di partenza della generazione', 'Starting point of generation')], [L('Diffusione latente', 'Latent diffusion'), L('Lavora in spazio compresso', 'Works in compressed space')], ['num_inference_steps', L('Passi di pulizia', 'Cleaning steps')], ['guidance_scale', L('Quanto seguire il prompt', 'How closely to follow the prompt')]], L('Dal rumore all’immagine.', 'From noise to image.')),
